<?php $editing = $mode === 'edit'; $action = $editing ? 'products/update/' . (int) $id : 'products'; ?>
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $editing ? 'Edit' : 'Add'; ?> Product | Product Desk</title><link rel="stylesheet" href="<?= base_url('css/auth_layout.css'); ?>"></head>
<body><main><nav><div class="brand">Product Desk</div><a href="<?= site_url('products'); ?>">Back to products</a></nav><section class="panel"><h1><?= $editing ? 'Edit product.' : 'Add a product.'; ?></h1><p class="muted">Keep the catalog details accurate and easy to scan.</p><?php if ($error): ?><div class="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8'); ?></div><?php endif; ?><form method="post" action="<?= site_url($action); ?>"><label>Product name<input name="product_name" maxlength="100" required value="<?= htmlspecialchars($product['product_name'] ?? '', ENT_QUOTES, 'UTF-8'); ?>"></label><label>Description<textarea name="description"><?= htmlspecialchars($product['description'] ?? '', ENT_QUOTES, 'UTF-8'); ?></textarea></label><label>Price<input type="number" name="price" min="0" step="0.01" required value="<?= htmlspecialchars($product['price'] ?? '', ENT_QUOTES, 'UTF-8'); ?>"></label><label>Quantity<input type="number" name="quantity" min="0" step="1" required value="<?= htmlspecialchars($product['quantity'] ?? '', ENT_QUOTES, 'UTF-8'); ?>"></label><div class="actions"><button type="submit"><?= $editing ? 'Save changes' : 'Add product'; ?></button><a class="button secondary" href="<?= site_url('products'); ?>">Cancel</a></div></form></section></main></body></html>
